    input: process.stdin,
    terminal: false
});

rl.on('line', (line) => {
    const str = line.trim();
    let t = 0;
    let i;
    for (i = 0; i < str.length; i++) {
        const val = str.charCodeAt(i) - 97;
        if (val > t) {
            console.log("NO");
            break;
        }
        if (val === t) {
            t++;
        }
    }
    if (i === str.length) {
        console.log("YES");
    }
});
